class Solution:
    def maxPrimeSubset(self, n: int, s: int) -> list[int]:
        primes = [x for x in range(2, n + 1) if all(x % d for d in range(2, int(x ** 0.5) + 1))]
        dp = {0: ()}
        for p in primes:
            for total, chosen in list(dp.items()):
                new = total + p
                if new <= s:
                    candidate = chosen + (p,)
                    old = dp.get(new)
                    if old is None or (len(candidate), candidate) < (len(old), old): dp[new] = candidate
        return list(dp[max(dp)])

